/**
 * Seals the answers, notes and dictionary of 解码与三国知识问答 into
 * src/sgjm/answers.generated.js (see src/sgjm/seal.js for how).
 *
 * Source: 文案/解码与三国知识问答_答案与解析.md, which is gitignored (the repo
 * is public); the generated file only holds hashes and ciphertext, so it is
 * committed and the site builds without the source. Run: npm run sgjm
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { SLOT_IDS } from '../src/sgjm/questions.js';
import { normalizeAnswer, checkOf, wrapKeyOf, contentKeyOf, dictionaryKeyOf, seal } from '../src/sgjm/seal.js';

const SRC = new URL('../文案/解码与三国知识问答_答案与解析.md', import.meta.url);
const OUT = new URL('../src/sgjm/answers.generated.js', import.meta.url);

// Blocks start with "# <id>" (one word); the sheet's title line has spaces and is skipped.
const blocks = new Map();
let current = null;
for (const line of readFileSync(SRC, 'utf8').replace(/\r\n/g, '\n').split('\n')) {
  const head = /^# (\S+)\s*$/.exec(line);
  if (head) blocks.set((current = head[1]), []);
  else if (current) blocks.get(current).push(line);
}

function parseSlot(id) {
  const body = blocks.get(id)?.join('\n');
  if (body == null) throw new Error(`答案表里没有「# ${id}」`);
  const a = /^答案[：:](.*)$/m.exec(body);
  if (!a) throw new Error(`${id}: 没有「答案：」这一行`);
  const names = a[1].split(/[/／]/).map((s) => s.trim()).filter(Boolean);
  const norms = [...new Set(names.map(normalizeAnswer).filter(Boolean))];
  if (!norms.length) throw new Error(`${id}: 答案是空的`);
  const n = /^解析[：:](.*)$/m.exec(body);
  const note = n ? body.slice(n.index + n[0].length - n[1].length).trim() : '';
  return { norms, note };
}

const slots = {};
const keys = [];
let names = 0;
for (const id of SLOT_IDS) {
  const { norms, note } = parseSlot(id);
  const key = await contentKeyOf(id, norms[0]);
  keys.push(key);
  const checks = {};
  for (const norm of norms) checks[await checkOf(id, norm)] = await seal(await wrapKeyOf(id, norm), key);
  slots[id] = { checks, note: await seal(key, note) };
  names += norms.length;
}
const dictionary = await seal(await dictionaryKeyOf(keys), (blocks.get('词典') ?? []).join('\n').trim());

const extra = [...blocks.keys()].filter((k) => k !== '词典' && !SLOT_IDS.includes(k));
if (extra.length) console.warn(`答案表里这些编号没有对应的题目，已忽略：${extra.join('、')}`);

writeFileSync(
  OUT,
  `// Generated by scripts/build-sgjm.mjs from the private answer sheet (文案/, not in the repo).
// Hashes and ciphertext only. Don't edit: change the sheet and run \`npm run sgjm\`.
export const SLOTS = {
${SLOT_IDS.map((id) => `  ${id}: ${JSON.stringify(slots[id])},`).join('\n')}
};
export const DICTIONARY = ${JSON.stringify(dictionary)};
`,
);
console.log(`sgjm: ${SLOT_IDS.length} 格，${names} 种写法，已写入 src/sgjm/answers.generated.js`);
